function seeded(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const run = (seed) => {
  const random = seeded(seed);
  return [random(), random(), random()].map((x) => Math.floor(x * 100)).join(",");
};
console.log(run(42) === run(42), run(42) === run(43));

