const replicas = ["a", "b", "c"];
const subsets = (size) => {
  const out = [];
  const pick = (start, chosen) => {
    if (chosen.length === size) return void out.push(chosen);
    for (let i = start; i < replicas.length; i++) pick(i + 1, [...chosen, replicas[i]]);
  };
  pick(0, []);
  return out;
};
const misses = (w, r) => {
  let count = 0;
  for (const writeSet of subsets(w)) {
    for (const readSet of subsets(r)) {
      if (!readSet.some((x) => writeSet.includes(x))) count++;
    }
  }
  return count;
};
console.log(`W=2 R=2: ${misses(2, 2)} misses, W=2 R=1: ${misses(2, 1)} misses`);

