function receive(own, remote, self) {
  const merged = { ...own };
  for (const [node, count] of Object.entries(remote)) {
    merged[node] = Math.max(merged[node] ?? 0, count);
  }
  merged[self] = (merged[self] ?? 0) + 1;
  return merged;
}

const laptop = { phone: 1, laptop: 3 };
const fromPhone = { phone: 4, laptop: 2, tablet: 1 };
