function inOrder(arrivals) {
  const waiting = new Set();
  const processed = [];
  let next = 1;
  for (const n of arrivals) {
    if (n < next) continue;
    waiting.add(n);
    while (waiting.has(next)) {
      waiting.delete(next);
      processed.push(next);
      next++;
    }
  }
  return processed;
}

